* {
  box-sizing: border-box;
  font-family: sans-serif;
}

.tag-container {
  border: 1px solid #ccc;
  padding: 5px;
  border-radius: 4px;
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  background: #fff;
}

.tag {
  background: #EBF4FF;
  color: #1E40AF;
  padding: 4px 8px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  font-size: 14px;
}

.tag .close-btn {
  margin-left: 6px;
  cursor: pointer;
  font-weight: bold;
}

#tagInput {
  border: none;
  outline: none;
  padding: 4px;
  flex-grow: 1;
  font-size: 14px;
}

