const tagContainer = document.getElementById('tagContainer');
const tagInput = document.getElementById('tagInput');

// Funktion zum Zeichnen der Tags aus dem Appsmith-Modell
function renderTags() {
  // Entferne alte Tags (behalte nur das Input-Feld)
  document.querySelectorAll('.tag').forEach(tag => tag.remove());

  // Sicheres Auslesen aus appsmith.model
  const tags = appsmith.model.tags || [];
  console.log(tags);
  tags.forEach((tag, index) => {
    const tagEl = document.createElement('div');
    tagEl.classList.add('tag');
    tagEl.innerHTML = `${tag} <span class="close-btn" data-index="${index}">&times;</span>`;
    tagContainer.insertBefore(tagEl, tagInput);
  });
}

// Event-Listener für neues Tag (Enter-Taste)
tagInput.addEventListener('keydown', e => {
  if (e.key === 'Enter' && tagInput.value.trim() !== '') {
    const currentTags = [...(appsmith.model.tags || [])];
    const newTag = tagInput.value.trim();
    if (!currentTags.includes(newTag)) {
      currentTags.push(newTag);

      // Modell in Appsmith aktualisieren
      appsmith.updateModel({
        tags: currentTags
      });
      appsmith.triggerEvent("onEnter");
    }
    tagInput.value = '';
  }
});

// Event-Listener zum Löschen eines Tags
tagContainer.addEventListener('click', e => {
  if (e.target.classList.contains('close-btn')) {
    const indexToRemove = parseInt(e.target.getAttribute('data-index'), 10);
    const currentTags = [...(appsmith.model.tags || [])];
    currentTags.splice(indexToRemove, 1);

    // Modell in Appsmith aktualisieren
    appsmith.updateModel({
      tags: currentTags
    });
    appsmith.triggerEvent("onEnter");
  }
});

// Initialisierung und Bindung an Appsmith-Datenänderungen
appsmith.onReady(() => {
  renderTags();

  // Lausche auf Änderungen des Modells (z.B. wenn sich appsmith.store.tagsList ändert)
  appsmith.onModelChange(model => {
    renderTags();
  });
});

